delete from iapp.appointment_transitions;
insert into iapp.appointment_transitions
select * from jsonb_populate_recordset(null::iapp.appointment_transitions, '[{"to_status": "PENDING", "description": "Staff picks up the request", "from_status": "REQUESTED", "allowed_roles": ["secretary", "admin", "doctor"], "sets_timestamp": "", "requires_reason": false}, {"to_status": "CONFIRMED", "description": "Approved directly", "from_status": "REQUESTED", "allowed_roles": ["secretary", "admin", "doctor"], "sets_timestamp": "confirmed_at", "requires_reason": false}, {"to_status": "CANCELLED", "description": "Rejected or withdrawn", "from_status": "REQUESTED", "allowed_roles": ["secretary", "admin", "doctor", "patient"], "sets_timestamp": "cancelled_at", "requires_reason": true}, {"to_status": "CONFIRMED", "description": "Secretary confirms the slot", "from_status": "PENDING", "allowed_roles": ["secretary", "admin", "doctor"], "sets_timestamp": "confirmed_at", "requires_reason": false}, {"to_status": "CANCELLED", "description": "Rejected or withdrawn", "from_status": "PENDING", "allowed_roles": ["secretary", "admin", "doctor", "patient"], "sets_timestamp": "cancelled_at", "requires_reason": true}, {"to_status": "REQUESTED", "description": "Returned to the queue", "from_status": "PENDING", "allowed_roles": ["secretary", "admin"], "sets_timestamp": "", "requires_reason": false}, {"to_status": "ARRIVED", "description": "Patient checks in", "from_status": "CONFIRMED", "allowed_roles": ["secretary", "admin", "doctor"], "sets_timestamp": "arrived_at", "requires_reason": false}, {"to_status": "CANCELLED", "description": "Cancelled before arrival", "from_status": "CONFIRMED", "allowed_roles": ["secretary", "admin", "doctor", "patient"], "sets_timestamp": "cancelled_at", "requires_reason": true}, {"to_status": "NO_SHOW", "description": "Did not attend", "from_status": "CONFIRMED", "allowed_roles": ["secretary", "admin", "doctor"], "sets_timestamp": "no_show_at", "requires_reason": false}, {"to_status": "PENDING", "description": "Un-confirmed for review", "from_status": "CONFIRMED", "allowed_roles": ["secretary", "admin", "doctor"], "sets_timestamp": "", "requires_reason": false}, {"to_status": "WAITING", "description": "Enters the waiting queue", "from_status": "ARRIVED", "allowed_roles": ["secretary", "admin", "doctor"], "sets_timestamp": "waiting_at", "requires_reason": false}, {"to_status": "CANCELLED", "description": "Left before being seen", "from_status": "ARRIVED", "allowed_roles": ["secretary", "admin", "doctor"], "sets_timestamp": "cancelled_at", "requires_reason": true}, {"to_status": "IN_CLINIC", "description": "Doctor calls the patient", "from_status": "WAITING", "allowed_roles": ["doctor", "admin"], "sets_timestamp": "in_clinic_at", "requires_reason": false}, {"to_status": "CANCELLED", "description": "Left the waiting room", "from_status": "WAITING", "allowed_roles": ["secretary", "admin", "doctor"], "sets_timestamp": "cancelled_at", "requires_reason": true}, {"to_status": "ARRIVED", "description": "Returned to arrived (correction)", "from_status": "WAITING", "allowed_roles": ["secretary", "admin", "doctor"], "sets_timestamp": "", "requires_reason": false}, {"to_status": "COMPLETED", "description": "Encounter finished", "from_status": "IN_CLINIC", "allowed_roles": ["doctor", "admin"], "sets_timestamp": "completed_at", "requires_reason": false}, {"to_status": "WAITING", "description": "Sent back to wait (correction)", "from_status": "IN_CLINIC", "allowed_roles": ["doctor", "admin"], "sets_timestamp": "", "requires_reason": false}, {"to_status": "CONFIRMED", "description": "Marked no-show in error", "from_status": "NO_SHOW", "allowed_roles": ["secretary", "admin"], "sets_timestamp": "", "requires_reason": false}, {"to_status": "ARRIVED", "description": "Arrived late after all", "from_status": "NO_SHOW", "allowed_roles": ["secretary", "admin"], "sets_timestamp": "arrived_at", "requires_reason": false}, {"to_status": "CONFIRMED", "description": "Cancellation reversed", "from_status": "CANCELLED", "allowed_roles": ["secretary", "admin"], "sets_timestamp": "confirmed_at", "requires_reason": false}]'::jsonb);

